func NewPortRangesValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (PortRangesValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing PortRangesValue Attribute Value",
				"While creating a PortRangesValue value, a missing attribute value was detected. "+
					"A PortRangesValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("PortRangesValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid PortRangesValue Attribute Type",
				"While creating a PortRangesValue value, an invalid attribute value was detected. "+
					"A PortRangesValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("PortRangesValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("PortRangesValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra PortRangesValue Attribute Value",
				"While creating a PortRangesValue value, an extra attribute value was detected. "+
					"A PortRangesValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra PortRangesValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewPortRangesValueUnknown(), diags
	}

	lowerAttribute, ok := attributes["lower"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`lower is missing from object`)

		return NewPortRangesValueUnknown(), diags
	}

	lowerVal, ok := lowerAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`lower expected to be basetypes.Int64Value, was: %T`, lowerAttribute))
	}

	upperAttribute, ok := attributes["upper"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`upper is missing from object`)

		return NewPortRangesValueUnknown(), diags
	}

	upperVal, ok := upperAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`upper expected to be basetypes.Int64Value, was: %T`, upperAttribute))
	}

	if diags.HasError() {
		return NewPortRangesValueUnknown(), diags
	}

	return PortRangesValue{
		Lower: lowerVal,
		Upper: upperVal,
		state: attr.ValueStateKnown,
	}, diags
}

func NewPortRangesValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) PortRangesValue {
	object, diags := NewPortRangesValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewPortRangesValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t PortRangesType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewPortRangesValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewPortRangesValueUnknown(), nil
	}

	if in.IsNull() {
		return NewPortRangesValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewPortRangesValueMust(PortRangesValue{}.AttributeTypes(ctx), attributes), nil
}

